const config = msg.config || global.get('houseConfig');
if (!config) { return [null, msg]; }

const houses = config.houses || (config.sensors ? [config] : []);
const allSensors = [];

for (const house of houses) {
    if (house.enabled === false) continue;
    const sensors = (house.sensors || []).filter(s => s.enabled && s.modbus && s.modbus.unitId != null && s.modbus.address != null);
    for (const sensor of sensors) {
        allSensors.push({
            houseId: house.houseId,
            sensorId: sensor.sensorId,
            unitId: sensor.modbus.unitId,
            fc: sensor.modbus.fc || 3,
            address: sensor.modbus.address,
            quantity: sensor.modbus.quantity || 1,
            registerIndex: sensor.modbus.registerIndex || 0,
            divider: sensor.modbus.divider || 1,
            signed: sensor.modbus.signed || false
        });
    }
}

if (allSensors.length === 0) {
    node.status({ fill: 'grey', shape: 'ring', text: 'Modbus 센서 없음' });
    msg.modbusReadings = {};
    return [null, msg];
}

// 같은 unitId+fc+address+quantity → 1회만 읽기
const uniqueReads = [];
const sensorMap = {};
for (const s of allSensors) {
    const key = s.unitId + ':' + s.fc + ':' + s.address + ':' + s.quantity;
    if (!sensorMap[key]) {
        sensorMap[key] = [];
        uniqueReads.push({
            key: key,
            unitId: s.unitId,
            fc: s.fc,
            address: s.address,
            quantity: s.quantity
        });
    }
    sensorMap[key].push(s);
}

flow.set('modbusUniqueReads', uniqueReads);
flow.set('modbusSensorMap', sensorMap);
flow.set('modbusReadIndex', 0);
flow.set('modbusReadings', {});
flow.set('modbusReadConfig', msg.config);

var first = uniqueReads[0];
msg.payload = {
    fc: first.fc,
    unitid: first.unitId,
    address: first.address,
    quantity: first.quantity
};
msg._modbusKey = first.key;

node.status({ fill: 'blue', shape: 'dot', text: 'Modbus 읽기 1/' + uniqueReads.length });
return [msg, null];

const uniqueReads = flow.get('modbusUniqueReads') || [];
const sensorMap = flow.get('modbusSensorMap') || {};
var idx = flow.get('modbusReadIndex') || 0;
var readings = flow.get('modbusReadings') || {};

var currentRead = uniqueReads[idx];
if (currentRead && msg.payload) {
    var sensors = sensorMap[currentRead.key] || [];
    for (var i = 0; i < sensors.length; i++) {
        var s = sensors[i];
        var rawValue = Array.isArray(msg.payload) ? msg.payload[s.registerIndex || 0] : msg.payload;
        var parsed = rawValue;
        if (s.signed && rawValue > 0x7FFF) {
            parsed = -(0xFFFF - rawValue + 1);
        }
        if (s.divider && s.divider !== 1) {
            parsed = parsed / s.divider;
        }
        parsed = Math.round(parsed * 100) / 100;
        readings[s.sensorId] = parsed;
    }
    flow.set('modbusReadings', readings);
}

idx++;
flow.set('modbusReadIndex', idx);

if (idx < uniqueReads.length) {
    var next = uniqueReads[idx];
    msg.payload = {
        fc: next.fc,
        unitid: next.unitId,
        address: next.address,
        quantity: next.quantity
    };
    msg._modbusKey = next.key;
    node.status({ fill: 'blue', shape: 'dot', text: 'Modbus 읽기 ' + (idx + 1) + '/' + uniqueReads.length });
    return [msg, null];
}

flow.set('modbusUniqueReads', []);
msg.modbusReadings = readings;
msg.config = flow.get('modbusReadConfig') || msg.config;
var count = Object.keys(readings).length;
node.status({ fill: 'green', shape: 'dot', text: 'Modbus 완료: ' + count + '개 센서' });
return [null, msg];

const uniqueReads = flow.get('modbusUniqueReads') || [];
var idx = flow.get('modbusReadIndex') || 0;

if (uniqueReads.length === 0 || idx >= uniqueReads.length) {
    return null;
}

var currentRead = uniqueReads[idx];
if (currentRead) {
    var sensorMap = flow.get('modbusSensorMap') || {};
    var sensors = sensorMap[currentRead.key] || [];
    var names = sensors.map(function(s) { return s.sensorId; }).join(',');
    node.warn('Modbus 읽기 실패: ' + names + ' (U' + currentRead.unitId + ':R' + currentRead.address + ')');
}

idx++;
flow.set('modbusReadIndex', idx);

if (idx < uniqueReads.length) {
    var next = uniqueReads[idx];
    msg.payload = {
        fc: next.fc,
        unitid: next.unitId,
        address: next.address,
        quantity: next.quantity
    };
    msg._modbusKey = next.key;
    node.status({ fill: 'yellow', shape: 'ring', text: '에러→다음 ' + (idx + 1) + '/' + uniqueReads.length });
    return [msg, null];
}

flow.set('modbusUniqueReads', []);
msg.modbusReadings = flow.get('modbusReadings') || {};
msg.config = flow.get('modbusReadConfig') || msg.config;
node.status({ fill: 'yellow', shape: 'dot', text: 'Modbus 완료 (일부 에러)' });
return [null, msg];
